// Checkout conversion module - ensures paid events are generated
const { log } = require('../utils/logger');
const { processPayment } = require('./payment-processor');

async function convertCheckout(session) {
  log('checkout-conversion', `Converting session ${session.id}`);
  // Simulate payment processing
  const result = await processPayment(session);
  if (result.success) {
    log('checkout-conversion', `Payment succeeded for session ${session.id}`);
    return { paid: true, amount: result.amount };
  }
  log('checkout-conversion', `Payment failed for session ${session.id}`);
  return { paid: false, error: result.error };
}

module.exports = { convertCheckout };
